SELECT DISTINCT #{state} as state, cookie as cjThreadId, ts - #{offset} as startTime, ts - #{offset} + dur AS endTime, dur as duration FROM callstack cs LEFT JOIN thread AS th ON th.id = cs.parent_id LEFT JOIN process AS p ON th.ipid = p.ipid WHERE cs.name LIKE 'H:CJTHREAD_CJThread' || #{state} AND cs.ts - #{offset} + cs.dur >= #{startTime} AND cs.ts - #{offset} <= #{endTime} AND cs.dur IS NOT NULL
AND p.pid in
#{pid}

SELECT DISTINCT SUBSTR(cs.name, 20) as state, cookie as cjThreadId, ts - #{offset} as startTime, ts - #{offset} + dur AS endTime, dur as duration FROM callstack cs LEFT JOIN thread AS th ON th.id = cs.parent_id LEFT JOIN process AS p ON th.ipid = p.ipid WHERE cs.name LIKE 'H:CJTHREAD_CJThread%' AND cs.ts - #{offset} + cs.dur >= #{startTime} AND cs.ts - #{offset} <= #{endTime} AND cs.name NOT LIKE 'H:CJTHREAD_CJThreadSetName%' AND cs.dur IS NOT NULL
AND p.pid in
#{pid}
